<script setup lang="ts">
import { computed,reactive,ref,onBeforeUnmount,watch } from 'vue'
import { X,Check,LoaderCircle,ChevronDown,Plus,Trash2,Cigarette,Wine,Heart } from 'lucide-vue-next'
import {recordDrafts} from '../drafts'
import { saveRow,state,refresh } from '../api'
import ProductEditor from './ProductEditor.vue'
import RecordTimeField from './RecordTimeField.vue'
import {productPrice,productOption,equivalent42,isOnlyMissingCostRepair} from '../productPricing'
import { localNow,money,number } from '../types'
import type { Row } from '../types'
const props=defineProps<{kind:'smoking'|'alcohol'|'intimacy';row?:Row;session?:Row}>();const emit=defineEmits<{close:[];saved:[row:Row,collection:string];refresh:[]}>()
const draftKey=`record:${props.kind}:${props.row?.id||props.session?.id||'new'}`,draft=recordDrafts[draftKey],submitted=ref(false),sessionCreateId=draft?.sessionCreateId||crypto.randomUUID()
const saveBase=ref<Row|undefined>(props.row)
const form=reactive<Record<string,any>>(draft?.form||(props.row?{...props.row}:{id:crypto.randomUUID(),occurredAt:localNow().slice(0,13)+':00:00',timePrecision:props.session?.timePrecision||'APPROX',productId:'',count:1,source:'SELF',mood:'',context:'',notes:'',manualAlcohol:'AUTO',overrideReason:'',durationMinutes:'',moodBefore:'',moodAfter:'',impact:'',unitPrice:'',purchaseId:''}))
const sessionCommitted=ref(!!draft?.sessionCommitted||!!draft?.drinkRows?.some((d:any)=>d.saved))
const details=ref(!!props.row),saving=ref(false),error=ref(''),sessionId=ref(draft?.sessionId||props.session?.id||'')
const sessionForm=reactive<Record<string,any>>(draft?.sessionForm||{startedAt:props.session?.startedAt||localNow().slice(0,13)+':00:00',endedAt:props.session?.endedAt||'',context:props.session?.context||'',notes:props.session?.notes||''})
const drinkRows=reactive<Record<string,any>[]>(draft?.drinkRows||[{id:crypto.randomUUID(),productId:'',inputMode:'BOTTLES',bottles:1,bottleMl:'',share:1,volumeMl:'',abv:'',unitPrice:'',purchaseId:'',occurredAt:props.session?.endedAt||props.session?.startedAt||sessionForm.startedAt,customTime:false,notes:''}])
const selectedSession=computed(()=>(state.collections.sessions||[]).find(s=>s.id===sessionId.value)||props.session)
const inheritedTime=computed(()=>{const s=sessionId.value&&selectedSession.value?selectedSession.value:sessionForm;return form.timePrecision==='DATE'?s.startedAt:s.endedAt||s.startedAt})
function syncTimes(){for(const d of drinkRows)if(!d.saved&&!d.customTime)d.occurredAt=inheritedTime.value}
watch(inheritedTime,syncTimes)
watch(sessionId,()=>{if(sessionId.value&&selectedSession.value)form.timePrecision=selectedSession.value.timePrecision||'APPROX';syncTimes()})
if(!draft)syncTimes()
const products=computed(()=>(state.collections.products||[]).filter(p=>p.kind===(props.kind==='smoking'?'SMOKING':'ALCOHOL')&&(p.active!==false||p.id===props.row?.productId)))
const currentProduct=computed(()=>products.value.find(p=>p.id===form.productId))
const price=computed(()=>productPrice(currentProduct.value,String(form.occurredAt).slice(0,10)))
const hasNumber=(v:any)=>v!==''&&v!=null
const samePriceInputs=computed(()=>!!saveBase.value&&form.productId===saveBase.value.productId&&new Date(form.occurredAt).getTime()===new Date(saveBase.value.occurredAt).getTime()&&(hasNumber(form.unitPrice)?Number(form.unitPrice):null)===(hasNumber(saveBase.value.unitPrice)?Number(saveBase.value.unitPrice):null))
const useHistoricalPrice=computed(()=>samePriceInputs.value&&saveBase.value?.snapshotUnitPrice!=null)
const priceSpecificationConflict=computed(()=>samePriceInputs.value&&saveBase.value?.cost==null&&saveBase.value?.snapshotUnitPrice==null&&!hasNumber(form.unitPrice)&&Number(saveBase.value?.snapshotUnitCount)>0&&Number(currentProduct.value?.unitCount)>0&&Number(saveBase.value?.snapshotUnitCount)!==Number(currentProduct.value?.unitCount))
const previewCost=computed(()=>{
 if(form.source==='GIFT')return 0
 if(samePriceInputs.value&&saveBase.value?.snapshotPurchasePayer==='OTHER')return 0
 if(priceSpecificationConflict.value)return null
 const packCount=saveBase.value&&form.productId===saveBase.value.productId?(saveBase.value.snapshotUnitCount??currentProduct.value?.unitCount):currentProduct.value?.unitCount
 const per=useHistoricalPrice.value?Number(saveBase.value!.snapshotUnitPrice):hasNumber(form.unitPrice)?Number(form.unitPrice):price.value.confirmed&&price.value.amount!=null&&Number(packCount)>0?price.value.amount/Number(packCount):null
 return per==null?null:per*Number(form.count)
})
const productTarget=ref<string|null>(null),productEditorRow=ref<Row|undefined>()
function openProduct(target:string,productId?:string){productEditorRow.value=productId?products.value.find(p=>p.id===productId):undefined;productTarget.value=target}
async function productSaved(row:Row){
 state.collections.products=[row,...(state.collections.products||[]).filter(p=>p.id!==row.id)]
 if(productTarget.value==='smoking')form.productId=row.id
 else{const drink=drinkRows.find(d=>d.id===productTarget.value);if(drink){drink.productId=row.id;productChanged(drink)}}
 productTarget.value=null;productEditorRow.value=undefined;saving.value=true
 try{
  await refresh()
  const before=saveBase.value
  if(props.kind==='smoking'&&before?.productId===row.id){
   const latest=state.collections.smoking?.find(r=>r.id===before.id)
   if(isOnlyMissingCostRepair(before,latest))saveBase.value=latest
  }
 }catch(e){error.value='种类已保存，但记录刷新失败：'+(e as Error).message}
 finally{saving.value=false;emit('refresh')}
}
function drinkPrice(d:Record<string,any>){return productPrice(products.value.find(p=>p.id===d.productId),String(d.occurredAt).slice(0,10))}
function drinkCost(d:Record<string,any>){const p=drinkPrice(d),unit=hasNumber(d.unitPrice)?Number(d.unitPrice):p.confirmed?p.amount:null;if(unit==null)return null;if(d.inputMode==='BOTTLES')return hasNumber(d.bottles)?Number(d.bottles)*Number(d.share??1)*unit:null;const ml=volume(d);return ml==null||!Number(d.bottleMl)?null:ml/Number(d.bottleMl)*unit}
function drinkEthanol(d:Record<string,any>){const ml=volume(d);return ml==null||!hasNumber(d.abv)?null:ml*Number(d.abv)/100*0.789}
const heading=computed(()=>props.kind==='smoking'?'记一笔吸烟':props.kind==='alcohol'?'记录这次饮酒':'留下一次记录')
const icon=computed(()=>props.kind==='smoking'?Cigarette:props.kind==='alcohol'?Wine:Heart)
function productChanged(d:Record<string,any>){const p=products.value.find(p=>p.id===d.productId);d.bottleMl=p?.bottleMl??'';d.abv=p?.abv??''}
if(!draft)drinkRows.forEach(productChanged)
onBeforeUnmount(()=>{if(!submitted.value)recordDrafts[draftKey]=JSON.parse(JSON.stringify({form,sessionForm,drinkRows,sessionId:sessionId.value,sessionCreateId,sessionCommitted:sessionCommitted.value}))})
function volume(d:Record<string,any>):number|null{if(d.inputMode==='ML')return d.volumeMl===''||d.volumeMl==null?null:Number(d.volumeMl);if(d.bottles===''||d.bottles==null||d.bottleMl===''||d.bottleMl==null)return null;return Number(d.bottles)*Number(d.bottleMl)*Number(d.share??1)}
function addDrink(){drinkRows.push({id:crypto.randomUUID(),productId:'',inputMode:'BOTTLES',bottles:1,bottleMl:'',share:1,volumeMl:'',abv:'',unitPrice:'',purchaseId:'',occurredAt:inheritedTime.value,customTime:false,notes:''})}
function clean(obj:Record<string,any>,collection:string){const keys=new Set(['id',...(state.schema.find(s=>s.name===collection)?.fields||[]).map(f=>f.key)]);return Object.fromEntries(Object.entries(obj).filter(([k])=>keys.has(k)).map(([k,v])=>[k,v===''?null:v]))}
async function submit(){saving.value=true;error.value='';try{
 if(props.kind==='smoking'&&!props.row&&!products.value.some(p=>p.id===form.productId&&p.active!==false))throw new Error('请先选择已启用的香烟种类，没有需要的种类可直接新增。')
 if(props.kind==='alcohol'&&drinkRows.some(d=>!d.productId))throw new Error('请先为每种酒选择种类，没有需要的种类可直接新增。')
 if(props.kind==='alcohol'){
  syncTimes()
  if(!sessionId.value){const r=await saveRow('sessions',clean({...sessionForm,endedAt:form.timePrecision==='DATE'?null:sessionForm.endedAt,id:sessionCreateId,timePrecision:form.timePrecision},'sessions'));sessionId.value=r.id;sessionCommitted.value=true}
  for(const d of drinkRows){if(d.saved)continue;await saveRow('drinks',clean({...d,sessionId:sessionId.value,timePrecision:form.timePrecision},'drinks'));d.saved=true;sessionCommitted.value=true}
  submitted.value=true;delete recordDrafts[draftKey];emit('saved',state.collections.sessions?.find(r=>r.id===sessionId.value)||{id:sessionId.value,version:1},'sessions')
 }else{const r=await saveRow(props.kind,clean(form,props.kind),saveBase.value);submitted.value=true;delete recordDrafts[draftKey];emit('saved',r,props.kind)}
 }catch(e){error.value=(e as Error).message+(sessionId.value&&props.kind==='alcohol'?' 已保存的场次会保留，重试只补充未保存的明细。':'');emit('refresh')}finally{saving.value=false}}
</script>
<template><div v-show="!productTarget" class="overlay" @click.self="emit('close')"><section class="drawer record-drawer" role="dialog" aria-modal="true" :aria-label="heading"><header class="drawer-header"><div class="heading-with-icon"><span class="icon-tile" :class="kind"><component :is="icon" :size="22"/></span><div><small>A MOMENT FOR YOURSELF</small><h2>{{heading}}</h2></div></div><button class="icon-button" title="关闭" @click="emit('close')"><X :size="20"/></button></header><form class="drawer-form" @submit.prevent="submit"><div class="drawer-body">
<p v-if="sessionCommitted" class="hint">这次已有内容保存，场次已固定；继续保存只会补充未保存的酒品。</p><p v-if="draft" class="hint">已恢复这次打开应用期间的未提交草稿。</p><div v-if="kind==='smoking'" class="record-primary"><label class="field"><span>这次抽了几根</span><div class="counter"><button type="button" @click="form.count=Math.max(1,Number(form.count)-1)">−</button><input aria-label="吸烟根数" v-model.number="form.count" type="number" min="1" step="1" required/><span>根</span><button type="button" @click="form.count=Number(form.count)+1">＋</button></div></label><label class="field"><span>先选择香烟种类 *</span><select v-model="form.productId" :required="!row"><option value="" disabled>请选择这次抽的种类</option><option v-for="p in products" :key="p.id" :value="p.id">{{productOption(p)}}</option></select></label><div class="entry-product-actions"><button type="button" class="text-link" @click="openProduct('smoking')"><Plus :size="15"/>没有想要的？新增种类</button><button v-if="currentProduct" type="button" class="text-link" @click="openProduct('smoking',currentProduct.id)">设置种类单价</button></div><p v-if="currentProduct" class="hint">{{price.confirmed?'种类单价 '+money(price.amount)+' / 包 · '+currentProduct.unitCount+' 根 / 包':'这个种类还没有确认单价，可点“设置种类单价”补充。'}}</p><div class="calculation-preview"><span>本次消耗成本预览</span><strong>{{previewCost==null&&!form.productId?'待选种类':priceSpecificationConflict?'待核对规格':money(previewCost)}}</strong><small>{{priceSpecificationConflict?'这条记录原有的每包根数与当前商品不同，请核对规格或填写本次单根价格。':useHistoricalPrice?'保留这条记录原有的单根价格，按本次根数计算。':'按种类单价 × 根数折算，不需要填写购买流水。'}}</small></div><div v-if="currentProduct" class="constituent-strip"><span>焦油 <b>{{currentProduct.tarMg??'—'}}</b></span><span>烟气烟碱 <b>{{currentProduct.nicotineMg??'—'}}</b></span><span>一氧化碳 <b>{{currentProduct.coMg??'—'}}</b></span><small>包装标示 mg/支，不是人体吸收量。低焦油不代表更安全。</small></div></div>
<template v-else-if="kind==='alcohol'"><label class="field"><span>记得多准确</span><select v-model="form.timePrecision"><option value="APPROX">大概时间（前后约 1 小时）</option><option value="DATE">只记得哪一天</option><option value="EXACT">记得具体时间</option></select></label><p class="hint">补记时选择日期和大概几点即可；每种酒默认沿用这次饮酒的结束时间，没填结束则沿用开始时间。</p><label class="field"><span>饮酒场次</span><select v-model="sessionId" :disabled="sessionCommitted||saving"><option value="">新建一次饮酒</option><option v-for="s in state.collections.sessions||[]" :key="s.id" :value="s.id">{{String(s.startedAt).replace('T',' ').slice(0,16)}} · {{s.context||'未填写场景'}}</option></select></label><div v-if="!sessionId" class="fields-grid"><RecordTimeField v-model="sessionForm.startedAt" :precision="form.timePrecision" label="这次饮酒开始" required/><RecordTimeField v-if="form.timePrecision!=='DATE'" v-model="sessionForm.endedAt" :precision="form.timePrecision" label="结束（选填）"/></div><p v-else class="hint">正在补充 {{String(selectedSession?.startedAt||'').slice(0,10)}} 的场次，新增酒品会沿用这个日期。</p><section v-for="(d,index) in drinkRows" :key="d.id" class="drink-item"><div class="section-line"><h3>酒品 {{index+1}}</h3><button v-if="drinkRows.length>1&&!d.saved" type="button" class="icon-button" title="移除此酒品" @click="drinkRows.splice(index,1)"><Trash2 :size="16"/></button><span v-if="d.saved" class="tag mint">已保存</span></div><fieldset :disabled="d.saved"><label class="field"><span>先选择酒品种类 *</span><select v-model="d.productId" @change="productChanged(d)" required><option value="" disabled>请选择这次喝的种类</option><option v-for="p in products" :key="p.id" :value="p.id">{{productOption(p)}} · {{p.bottleMl}} ml</option></select></label><div class="entry-product-actions"><button type="button" class="text-link" @click="openProduct(d.id)"><Plus :size="15"/>没有想要的？新增种类</button><button v-if="d.productId" type="button" class="text-link" @click="openProduct(d.id,d.productId)">设置种类单价</button></div><p v-if="d.productId" class="hint">{{drinkPrice(d).confirmed?'种类单价 '+money(drinkPrice(d).amount)+' / 瓶':'这个种类的单价待确认，保存前可直接补充。'}}</p><div class="segmented"><button type="button" :class="{active:d.inputMode==='BOTTLES'}" @click="d.inputMode='BOTTLES'">按瓶 / 罐</button><button type="button" :class="{active:d.inputMode==='ML'}" @click="d.inputMode='ML'">直接记毫升</button></div><div class="fields-grid"><template v-if="d.inputMode==='BOTTLES'"><label class="field"><span>瓶数</span><input type="number" v-model.number="d.bottles" min="0.01" step="0.01" required/></label><label class="field"><span>每瓶容量 · ml</span><input type="number" v-model.number="d.bottleMl" min="1" step="any" required/></label><label class="field"><span>自己喝的比例</span><select v-model.number="d.share"><option :value="1">全部</option><option :value="0.75">四分之三</option><option :value="0.5">一半</option><option :value="0.333333">三分之一</option><option :value="0.25">四分之一</option></select></label></template><label v-else class="field"><span>本人实际饮用 · ml</span><input type="number" v-model.number="d.volumeMl" min="0.1" step="any" required/></label><label class="field"><span>酒精度 · % vol</span><input type="number" v-model.number="d.abv" min="0" max="100" step="any" placeholder="未知可留空"/></label><div class="field full"><label class="time-override"><input v-model="d.customTime" type="checkbox" @change="syncTimes"/><span>单独设置这杯 / 这种酒的时间</span></label><p v-if="!d.customTime" class="hint">沿用场次：{{String(d.occurredAt).slice(0,10)}}{{form.timePrecision==='DATE'?'（只记日期）':form.timePrecision==='APPROX'?' 约 '+String(d.occurredAt).slice(11,13)+' 点':' '+String(d.occurredAt).slice(11,16)}}</p><RecordTimeField v-else v-model="d.occurredAt" :precision="form.timePrecision" label="这款酒的饮用时间" required/></div><label v-if="details" class="field"><span>本次单瓶单价覆盖 · 元（选填）</span><input type="number" v-model.number="d.unitPrice" min="0" step="0.01" placeholder="留空采用种类单价"/></label></div><div class="calculation-preview"><span>本人饮用 <strong>{{volume(d)==null?'—':number(volume(d))}} ml</strong></span><span>折合 42 度白酒 <strong>{{drinkEthanol(d)==null?'—':number(equivalent42(drinkEthanol(d)),1)}} ml</strong></span><span>本次费用 <strong>{{money(drinkCost(d))}}</strong></span><small>纯酒精 {{drinkEthanol(d)==null?'待补酒精度':number(drinkEthanol(d),2)+' g'}}；白酒换算仅比较酒精量。</small></div></fieldset></section><button type="button" class="button secondary full-width" @click="addDrink"><Plus :size="17"/>继续添加一种酒</button><p class="muted small">酒量和费用均按本人饮用量计算。多人分饮请调整比例，无需录入购买流水。</p></template>
<template v-else><div class="intimacy-note"><Heart :size="27"/><h3>给自己一点空间。</h3><p>如实记录就好，留意自己的舒适程度与休息。</p></div><label class="field"><span>次数</span><div class="counter"><button type="button" @click="form.count=Math.max(1,Number(form.count)-1)">−</button><input aria-label="次数" v-model.number="form.count" type="number" min="1" step="1" required/><span>次</span><button type="button" @click="form.count=Number(form.count)+1">＋</button></div></label><p class="hint">系统会根据已记录的饮酒时间自动关联；缺少信息时会保留不确定状态。</p></template>
<div v-if="kind!=='alcohol'" class="fields-grid"><label class="field"><span>记得多准确</span><select v-model="form.timePrecision"><option value="APPROX">大概时间（前后约 1 小时）</option><option value="DATE">只记得哪一天</option><option value="EXACT">记得具体时间</option></select></label><RecordTimeField v-model="form.occurredAt" :precision="form.timePrecision" label="实际发生" required/></div><button type="button" class="detail-toggle" @click="details=!details">{{details?'收起':'补充'}}详细信息 <ChevronDown :size="17" :class="{rotated:details}"/></button>
<div v-if="details" class="fields-grid"><template v-if="kind==='smoking'"><label class="field"><span>来源</span><select v-model="form.source"><option value="SELF">自购</option><option value="GIFT">别人提供</option><option value="OTHER">其他</option></select></label><label class="field"><span>单根采用价 · 元（选填）</span><input v-model.number="form.unitPrice" type="number" min="0" step="0.001" placeholder="自动计算"/></label><label class="field"><span>情绪</span><select v-model="form.mood"><option value="">暂不填写</option><option>平静</option><option>放松</option><option>压力</option><option>烦躁</option><option>无聊</option></select></label><label class="field"><span>场景</span><input v-model="form.context" placeholder="如：饭后、工作间隙"/></label></template><template v-if="kind==='intimacy'"><label class="field"><span>时长 · 分钟（选填）</span><input v-model.number="form.durationMinutes" type="number" min="0" step="any"/></label><label class="field"><span>之前的感受</span><input v-model="form.moodBefore" placeholder="如：放松、压力"/></label><label class="field"><span>之后的感受</span><input v-model="form.moodAfter" placeholder="如：舒适、疲惫"/></label><label class="field"><span>对生活的影响</span><select v-model="form.impact"><option value="">暂不填写</option><option value="NONE">没有影响</option><option value="SLEEP">影响休息</option><option value="WORK">影响工作或学习</option><option value="DISCOMFORT">有不适</option></select></label><label class="field"><span>是否酒后</span><select v-model="form.manualAlcohol"><option value="AUTO">交给系统关联</option><option value="YES">本人确认是</option><option value="NO">本人确认不是</option><option value="UNKNOWN">不确定</option></select></label><label v-if="form.manualAlcohol!=='AUTO'" class="field"><span>更正说明</span><input v-model="form.overrideReason" required placeholder="请说明本人确认或更正的依据"/></label></template><label v-if="kind==='alcohol'&&!sessionId" class="field"><span>场景</span><input v-model="sessionForm.context" placeholder="如：聚餐、独饮"/></label><label v-if="kind!=='alcohol'||!sessionId" class="field full"><span>备注（选填）</span><textarea v-if="kind==='alcohol'" v-model="sessionForm.notes" rows="3"/><textarea v-else v-model="form.notes" rows="3"/></label></div><p v-if="error" class="error-box" role="alert">{{error}}</p></div><footer class="drawer-footer"><span class="muted small">只保存在这台电脑</span><button class="button primary" :disabled="saving"><LoaderCircle v-if="saving" :size="17" class="spin"/><Check v-else :size="17"/>{{saving?'正在保存':'保存记录'}}</button></footer></form></section></div><ProductEditor v-if="productTarget" :row="productEditorRow" :kind="kind==='smoking'?'SMOKING':'ALCOHOL'" @close="productTarget=null;productEditorRow=undefined" @saved="productSaved"/></template><style scoped>.time-override{display:flex;align-items:center;gap:9px;font-size:12px}.time-override input{width:15px}.time-override+.hint{margin-top:8px}.entry-product-actions{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:-4px 0 16px}.calculation-preview{flex-wrap:wrap;gap:10px}.calculation-preview small{flex-basis:100%}</style>
